package com.ssk.kiosk.integration;
import java.time.Instant;import java.util.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class IntegrationConfigurationService {private final IntegrationConfigurationRepository repository;public IntegrationConfigurationService(IntegrationConfigurationRepository r){repository=r;}public List<IntegrationConfiguration> all(){return repository.findAll();}@Transactional public IntegrationConfiguration update(String key,Map<String,Object> values,String actor){IntegrationConfiguration c=repository.findById(key.toUpperCase(Locale.ROOT)).orElseThrow();c.setEnabled(Boolean.TRUE.equals(values.get("enabled")));c.setBaseUrl(String.valueOf(values.getOrDefault("baseUrl","")));c.setConnectTimeoutMs(range(values,"connectTimeoutMs",500,60000));c.setReadTimeoutMs(range(values,"readTimeoutMs",500,120000));c.setRetryCount(range(values,"retryCount",0,5));c.setUpdatedAt(Instant.now());c.setUpdatedBy(actor);return repository.save(c);}private int range(Map<String,Object>v,String key,int min,int max){int n=((Number)v.getOrDefault(key,min)).intValue();if(n<min||n>max)throw new IllegalArgumentException(key+" outside permitted range");return n;}}
